# Better: work in uint8 space
def add_patch_uint8(img_uint8, patch_size=3, corner='top_left', patch_type='white'):
    """Add patch to uint8 image (0-255)"""
    img = img_uint8.clone()
    if corner == 'top_left':
        h_start, w_start = 1, 1
    elif corner == 'top_right':
        h_start, w_start = 1, 32 - 1 - patch_size
    elif corner == 'bottom_left':
        h_start, w_start = 32 - 1 - patch_size, 1
    elif corner == 'bottom_right':
        h_start, w_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    h_end = h_start + patch_size
    w_end = w_start + patch_size

    if patch_type == 'white':
        img[:, :, h_start:h_end, w_start:w_end] = 255
    elif patch_type == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, :, h_start + i, w_start + j] = val
    elif patch_type == 'noise':
        img[:, :, h_start:h_end, w_start:w_end] = torch.randint(0, 256, (3, patch_size, patch_size))

    return img

